-- Comentarios do CTN, lote 3 (arts. 41 a 66). Autorizados pela Jessica em 22/10/2026; so a partir do texto no banco.
-- Reverter: update legislacao set contexto=null, aplicacao_pratica=null where codigo='ctn' and numero between 41 and 66 and paragrafo is null and inciso is null;
update legislacao l set contexto=v.c, aplicacao_pratica=v.a from (values
(41,'','ITBI: competência','O imposto compete ao Município da situação do bem, ou ao Distrito Federal, na redação dada pela Lei Complementar n. 227, de 2026.'),
(42,'','ITBI: contribuinte','Contribuinte do imposto é qualquer das partes na operação tributada, como dispuser a lei.'),
(43,'','Imposto de renda: fato gerador','O imposto, de competência da União, sobre a renda e proventos de qualquer natureza tem como fato gerador a aquisição da disponibilidade econômica ou jurídica de renda, assim entendido o produto do capital, do trabalho ou da combinação de ambos (inciso I), e de proventos de qualquer natureza, assim entendidos os acréscimos patrimoniais não compreendidos no inciso anterior (inciso II). O § 1º dispõe que a incidência independe da denominação da receita ou do rendimento, da localização, condição jurídica ou nacionalidade da fonte, da origem e da forma de percepção. O § 2º dispõe que, na hipótese de receita ou rendimento oriundos do exterior, a lei estabelecerá as condições e o momento em que se dará sua disponibilidade, para fins de incidência do imposto.'),
(44,'','Imposto de renda: base de cálculo','A base de cálculo do imposto é o montante, real, arbitrado ou presumido, da renda ou dos proventos tributáveis.'),
(45,'','Imposto de renda: contribuinte e responsável','Contribuinte do imposto é o titular da disponibilidade a que se refere o art. 43, sem prejuízo de atribuir a lei essa condição ao possuidor, a qualquer título, dos bens produtores de renda ou dos proventos tributáveis. O parágrafo único dispõe que a lei pode atribuir à fonte pagadora da renda ou dos proventos tributáveis a condição de responsável pelo imposto cuja retenção e recolhimento lhe caibam.'),
(46,'','IPI: fato gerador','O imposto, de competência da União, sobre produtos industrializados tem como fato gerador o seu desembaraço aduaneiro, quando de procedência estrangeira (inciso I); a sua saída dos estabelecimentos a que se refere o parágrafo único do art. 51 (inciso II); e a sua arrematação, quando apreendido ou abandonado e levado a leilão (inciso III). O parágrafo único dispõe que, para os efeitos do imposto, considera-se industrializado o produto que tenha sido submetido a qualquer operação que lhe modifique a natureza ou a finalidade, ou o aperfeiçoe para o consumo.'),
(47,'','IPI: base de cálculo','A base de cálculo do imposto é, no caso do inciso I do artigo anterior, o preço normal, como definido no inciso II do art. 20, acrescido do montante do imposto sobre a importação, das taxas exigidas para entrada do produto no País e dos encargos cambiais efetivamente pagos pelo importador ou dele exigíveis (inciso I, alíneas a a c). No caso do inciso II do artigo anterior, é o valor da operação de que decorrer a saída da mercadoria ou, na falta dele, o preço corrente da mercadoria, ou sua similar, no mercado atacadista da praça do remetente (inciso II, alíneas a e b). No caso do inciso III, é o preço da arrematação (inciso III).'),
(48,'','IPI: seletividade','O imposto é seletivo em função da essencialidade dos produtos.'),
(49,'','IPI: não-cumulatividade','O imposto é não-cumulativo, dispondo a lei de forma que o montante devido resulte da diferença a maior, em determinado período, entre o imposto referente aos produtos saídos do estabelecimento e o pago relativamente aos produtos nele entrados. O parágrafo único dispõe que o saldo verificado, em determinado período, em favor do contribuinte transfere-se para o período ou períodos seguintes.'),
(50,'','IPI: nota fiscal nas remessas interestaduais','Os produtos sujeitos ao imposto, quando remetidos de um para outro Estado, ou do ou para o Distrito Federal, serão acompanhados de nota fiscal de modelo especial, emitida em séries próprias e contendo, além dos elementos necessários ao controle fiscal, os dados indispensáveis à elaboração da estatística do comércio por cabotagem e demais vias internas.'),
(51,'','IPI: contribuinte','Contribuinte do imposto é o importador ou quem a lei a ele equiparar (inciso I); o industrial ou quem a lei a ele equiparar (inciso II); o comerciante de produtos sujeitos ao imposto, que os forneça aos contribuintes definidos no inciso anterior (inciso III); e o arrematante de produtos apreendidos ou abandonados, levados a leilão (inciso IV). O parágrafo único dispõe que, para os efeitos do imposto, considera-se contribuinte autônomo qualquer estabelecimento de importador, industrial, comerciante ou arrematante.'),
(63,'','IOF: fato gerador','O imposto, de competência da União, sobre operações de crédito, câmbio e seguro, e sobre operações relativas a títulos e valores mobiliários tem como fato gerador, quanto às operações de crédito, a sua efetivação pela entrega total ou parcial do montante ou do valor que constitua o objeto da obrigação, ou sua colocação à disposição do interessado (inciso I); quanto às de câmbio, a sua efetivação pela entrega de moeda nacional ou estrangeira, ou de documento que a represente, ou sua colocação à disposição do interessado em montante equivalente (inciso II); quanto às de seguro, a sua efetivação pela emissão da apólice ou do documento equivalente, ou recebimento do prêmio, na forma da lei aplicável (inciso III); e quanto às relativas a títulos e valores mobiliários, a emissão, transmissão, pagamento ou resgate destes, na forma da lei aplicável (inciso IV). O parágrafo único dispõe que a incidência definida no inciso I exclui a definida no inciso IV, e reciprocamente, quanto à emissão, ao pagamento ou resgate do título representativo de uma mesma operação de crédito.'),
(64,'','IOF: base de cálculo','A base de cálculo do imposto é, quanto às operações de crédito, o montante da obrigação, compreendendo o principal e os juros (inciso I); quanto às de câmbio, o respectivo montante em moeda nacional, recebido, entregue ou posto à disposição (inciso II); quanto às de seguro, o montante do prêmio (inciso III); e, quanto às relativas a títulos e valores mobiliários, na emissão, o valor nominal mais o ágio, se houver, na transmissão, o preço ou o valor nominal, ou o valor da cotação em Bolsa, como determinar a lei, e, no pagamento ou resgate, o preço (inciso IV, alíneas a a c).'),
(65,'','IOF: alteração de alíquotas e bases pelo Executivo','O Poder Executivo pode, nas condições e nos limites estabelecidos em lei, alterar as alíquotas ou as bases de cálculo do imposto, a fim de ajustá-lo aos objetivos da política monetária.'),
(66,'','IOF: contribuinte','Contribuinte do imposto é qualquer das partes na operação tributada, como dispuser a lei.')
) as v(n,t,c,a)
where l.codigo='ctn' and l.numero=v.n and coalesce(l.titulo,'')=v.t and l.paragrafo is null and l.inciso is null and l.vigente;
